const nextSlot = st => { const x=SLOT_STEPS.find(([lv])=>st<lv); return x?x[0]:null; };
const slotText = st => { const n=slots(st), nx=nextSlot(st); return `${n}/8 ô` + (nx?` · ô kế mở ở ${nx}★`:` · đã mở hết`); };
