function showTab(id){
  document.querySelectorAll("nav button").forEach(b=>b.setAttribute("aria-selected", b.dataset.tab===id));
  document.querySelectorAll("main section").forEach(s=>s.hidden = s.id!==id);
  store.set("tab",id); window.scrollTo(0,0);
}

/* teams */
