const modesEl = document.getElementById("modes");
DATA.teams.forEach((t,i)=>{
  const b=document.createElement("button"); b.textContent=t.name; b.setAttribute("aria-pressed",i===curTeam);
  b.addEventListener("click",()=>{ curTeam=i; store.set("team",i); [...modesEl.children].forEach((x,j)=>x.setAttribute("aria-pressed",j===i)); renderTeam(); });
  modesEl.appendChild(b);
});
function bondsOf(t){
  const names=[...t.front,...t.back], out=[];
  names.forEach(n=>{ const h=byName[n]; const partner=(h.tn||"").split(" – ")[0].split(" (")[0].trim();
    if(names.includes(partner) && !out.some(o=>o.includes(n))) out.push(`${n} + ${partner}` + ((h.tn||"").includes("–") ? " · "+h.tn.split("– ")[1] : "")); });
  return out;
}
function renderTeam(){
  const t=DATA.teams[curTeam], key=mk(t.mode), all=[...t.front,...t.back];
  const avg=key?(all.reduce((s,n)=>s+(byName[n][key]||0),0)/all.length).toFixed(1):null;
  const slot=n=>{const h=byName[n];return `<button class="slot" data-h="${esc(n)}">${token(h)}<span class="nm">${esc(n)}</span><span class="tg">${esc(h.phe)} · ${esc(h.nhom)}</span></button>`};
  const bonds=bondsOf(t);
  const pos=[...t.front.map((n,i)=>["Ô "+(i+1),n]),...t.back.map((n,i)=>["Ô "+(i+4),n])];
  document.getElementById("teamview").innerHTML=`
  <div class="team">
    <div>
      <div class="board">
        <div class="board-head"><h3>${esc(t.name)}</h3><span class="score">${avg===null?esc(t.score||"Theo điều kiện trận"):`Điểm ${esc(t.mode)} TB <b>${avg}</b>/5`}</span></div>
        <div class="enemy">↑ Phía địch</div>
        <div class="rowlab">Hàng trước</div><div class="row front">${t.front.map(slot).join("")}</div>
        <div class="rowlab">Hàng sau</div><div class="row back">${t.back.map(slot).join("")}</div>
        <div class="bonds">${bonds.length?bonds.map(b=>`<span class="chip on">Tình Nghĩa: ${esc(b)}</span>`).join(""):`<span class="chip">Không có Tình Nghĩa kích hoạt</span>`}</div>
      </div>
      <div class="note">${esc(t.note)}</div>
    </div>
    <div class="roles">${pos.map(([p,n])=>{const h=byName[n];return `<button class="role" data-h="${esc(n)}">${token(h)}<span><span class="t">${esc(n)}</span><br><span class="d">${esc(t.why[n])}</span></span><span class="pos">${p}</span></button>`}).join("")}</div>
  </div>`;
}
