function openHero(n){
  const h=byName[n]; if(!h) return;
  document.getElementById("dlg-token").innerHTML=token(h);
  document.getElementById("dlg-title").textContent=h.name;
  document.getElementById("dlg-meta").textContent=`${h.phe} · ${h.nhom} · ${h.sao}★ hiện tại · ${h.keep}`;
  const teams=DATA.teams.filter(t=>[...t.front,...t.back].includes(n)).map(t=>t.name);
  const step=(lv,txt,need)=>{const cut=/Chưa có|bị cắt/.test(txt||""); return `<li><span class="lv ${h.sao>=need?"reached":""}">${lv}</span><span class="${cut?"cut":""}">${esc(txt)}</span></li>`};
  document.getElementById("dlg-body").innerHTML=`
    <dl class="kv">
      <dt>Vai trò</dt><dd>${esc(h.role)}</dd>
      <dt>Kỹ năng</dt><dd>${esc(h.base)}</dd>
      <dt>Tình Nghĩa</dt><dd>${esc(h.tn)}</dd>
      <dt>Điểm</dt><dd>PVP ${h.pvp??"–"} · Boss ${h.boss??"–"} · PVE ${h.pve??"–"}</dd>
      ${h.stat?`<dt>Server mới</dt><dd>${esc(h.stat)}</dd>`:""}
      <dt>Công pháp</dt><dd>${slotText(h.sao)}</dd>
      <dt>Có trong đội</dt><dd>${teams.length?esc(teams.join(", ")):"Dự bị"}</dd>
      ${h.gear?`<dt>Trang bị</dt><dd>${esc(h.gear)}</dd>`:""}
      ${h.books?`<dt>Kỳ sách</dt><dd>${esc(h.books)}</dd>`:""}
    </dl>
    <div><div class="rowlab">Tiềm năng (màu xanh = đã đạt)</div>
    <ol class="steps">${step("9★",h.s9,9)}${step("11★",h.s11,11)}${step("13★",h.s13,13)}${step("Nhập Thánh",h.nt,16)}</ol></div>`;
  dlg.showModal();
}

