const RULE={5:{copy:1,fs:5,fc:1,orb:null},6:{copy:0,fs:5,fc:2,orb:1000},7:{copy:0,fs:6,fc:1,orb:1000},8:{copy:1,fs:8,fc:1,orb:2000},
 9:{copy:null,fs:null,fc:null,orb:null},10:{copy:1,fs:8,fc:1,orb:3000},11:{copy:0,fs:6,fc:1,orb:2000},12:{copy:1,fs:8,fc:1,orb:5000},13:{copy:0,fs:6,fc:2,orb:2500}};
const CORE=new Set(DATA.teams.flatMap(t=>[...t.front,...t.back]));
let K, KLOG, KUNDO, ORB, kf="Tất cả";
function normalizeInventory(raw){
 if(!Array.isArray(raw))return null;
 const ids=new Set(),out=[];
 raw.forEach((u,i)=>{if(!u||typeof u.name!=="string"||!u.name.trim())return;let id=Number.isInteger(+u.id)&&+u.id>0?+u.id:i+1;while(ids.has(id))id++;ids.add(id);
  out.push({id,name:u.name.trim(),phe:u.phe||"3Q",star:Math.max(1,Math.min(20,+u.star||5)),r:u.r==="SSR"?"SSR":"SSR+"});});
 return out;
}
function kload(){try{const s=JSON.parse(localStorage.getItem("kho2")||"null"),inventory=normalizeInventory(s&&s.k);if(inventory){K=inventory;KLOG=Array.isArray(s.log)?s.log:[];KUNDO=Array.isArray(s.undo)?s.undo:[];ORB=Math.max(0,+s.orb||0);return}}catch(e){}
 K=KDEF.map((u,i)=>({...u,id:i+1}));KLOG=[];KUNDO=[];ORB=10779;}
function ksave(){try{localStorage.setItem("kho2",JSON.stringify({k:K,log:KLOG,undo:KUNDO.slice(-30),orb:ORB}));localStorage.setItem("cash",String(ORB))}catch(e){}}
function snap(){KUNDO.push(JSON.stringify({k:K,orb:ORB,log:KLOG}))}
const nid=()=>K.reduce((m,u)=>Math.max(m,u.id),0)+1;
const today=()=>new Date().toLocaleString("vi-VN",{day:"2-digit",month:"2-digit",hour:"2-digit",minute:"2-digit"});
function syncHeroes(){H.forEach(h=>{const us=K.filter(u=>u.name===h.name);if(us.length){h.sao=Math.max(...us.map(u=>u.star));h.ban=us.length}else{h.sao=h._baseSao??h.sao;h.ban=0}});
 const c=document.getElementById("cash");if(c){c.value=ORB;renderUp()}renderGrid();renderTeam();
 const sp=document.getElementById("slotplan");if(sp){const core=[...new Set(DATA.teams.filter(t=>t.mode==="PVP"||t.mode==="Boss").flatMap(t=>[...t.front,...t.back]))];sp.querySelectorAll("tbody tr").forEach((tr,i)=>{const h=byName[core[i]],td=tr.children;if(!h)return;if(td[1])td[1].textContent=h.sao+"★";if(td[2])td[2].textContent=slots(h.sao);if(td[3])td[3].textContent=nextSlot(h.sao)?nextSlot(h.sao)+"★":"–";});}
 const al=document.getElementById("alloc");if(al)al.querySelectorAll(".ab").forEach(el=>{const n=el.querySelector(".ab-h b")?.textContent,h=byName[n];if(!h)return;const m=el.querySelector(".ab-h .meta");if(m)m.textContent=h.sao+"★ · "+slots(h.sao)+" ô";const bk=el.querySelector(".bk");if(bk){bk.querySelectorAll(".empty-slot").forEach(x=>x.remove());for(let k=0;k<Math.max(0,slots(h.sao)-(DATA.alloc[n]||[]).length);k++){const x=document.createElement("span");x.className="bchip empty-slot";x.textContent="Ô trống";bk.appendChild(x);}}});
 try{renderSampleTeam(sampleTeamMode);renderSampleUpgrade()}catch(e){}
}
const kfEl=document.getElementById("kFilter");
["Tất cả","3Q","Hán","Tần","Đường","SSR+","SSR (nguyên liệu)"].forEach(v=>{const b=document.createElement("button");b.textContent=v;b.dataset.v=v;b.setAttribute("aria-pressed",v===kf);
 b.onclick=()=>{kf=v;[...kfEl.children].forEach(x=>x.setAttribute("aria-pressed",x.dataset.v===v));krender()};kfEl.appendChild(b)});
const stars=s=>`${s}★`;
function validateUpgrade(u,ids){
 const rule=RULE[u.star];if(!rule||rule.copy==null||rule.fs==null||rule.fc==null)return "";
 const used=K.filter(x=>ids.includes(x.id));
 const copies=used.filter(x=>x.name===u.name).length;
 const fodder=used.filter(x=>x.phe===u.phe&&x.star===rule.fs&&x.name!==u.name).length;
 if(rule.copy&&copies<rule.copy)return `Cần chọn ${rule.copy} bản trùng ${u.name}.`;
 if(fodder<rule.fc)return `Cần chọn ${rule.fc} tướng ${u.phe} ${rule.fs}★ làm nguyên liệu.`;
 return "";
}
function renderKhoMatrix(){
 const matrixBox=document.getElementById("kho-matrix-result"),radarBox=document.getElementById("kho-radar-chart");
 if(!matrixBox||!radarBox)return;
 const groups={};K.forEach(u=>{(groups[u.name]=groups[u.name]||[]).push(u)});
 const names=Object.keys(groups).sort((a,b)=>a.localeCompare(b,"vi"));
 const cols=sampleMatrixCols();
 if(!names.length){matrixBox.innerHTML='<p class="empty">Kho chưa có tướng.</p>';radarBox.innerHTML="";return;}
 const scored=names.map(name=>{const maxStar=Math.max(...groups[name].map(u=>u.star));const sc=sampleHeroMatrixScore(name);return {name,count:groups[name].length,star:maxStar,sc,known:!!SAMPLE_HERO_STATS[name]};});
 const headers=cols.map(c=>'<th>'+c[1]+'</th>').join("");
 const rows=scored.map(item=>'<tr><td>'+esc(item.name)+' <span class="meta">×'+item.count+'</span></td>'+cols.map(c=>{const v=item.known?item.sc[c[0]]:"—";return '<td class="'+(v===5?"score-high":v===1?"score-low":"")+'">'+v+'</td>';}).join("")+'</tr>').join("");
 const known=scored.filter(x=>x.known);
 const totals=cols.map(c=>'<td><b>'+known.reduce((sum,x)=>sum+x.sc[c[0]],0)+'</b></td>').join("");
 matrixBox.innerHTML='<table class="sample-matrix"><thead><tr><th>Tướng trong kho</th>'+headers+'</tr></thead><tbody>'+rows+'<tr class="matrix-total"><th>Tổng điểm ('+known.length+' tướng có dữ liệu)</th>'+totals+'</tr></tbody></table>';
 const totalsByCol=cols.map(c=>known.reduce((sum,x)=>sum+x.sc[c[0]],0));
 const max=Math.max(1,known.length*5),cx=180,cy=155,r=94,angle=i=>-Math.PI/2+i*2*Math.PI/cols.length;
 const point=(i,v)=>[cx+Math.cos(angle(i))*r*Math.max(0,Math.min(max,v))/max,cy+Math.sin(angle(i))*r*Math.max(0,Math.min(max,v))/max];
 const poly=arr=>arr.map(p=>p.map(n=>n.toFixed(1)).join(",")).join(" ");
 let grid="";
 for(let level=1;level<=5;level++)grid+='<polygon points="'+poly(cols.map((_,i)=>point(i,max*level/5)))+'" fill="none" stroke="var(--line)" stroke-width="1"/>';
 const spokes=cols.map((c,i)=>{const p=point(i,max);return '<line x1="'+cx+'" y1="'+cy+'" x2="'+p[0]+'" y2="'+p[1]+'" stroke="var(--line)"/>';}).join("");
 const shape=cols.map((c,i)=>point(i,totalsByCol[i]));
 const labels=cols.map((c,i)=>{const p=point(i,max*1.22);return '<text x="'+p[0]+'" y="'+(p[1]+4)+'" text-anchor="middle" fill="var(--ink)" font-size="10" font-weight="600">'+c[1]+'</text>';}).join("");
 const legend=cols.map((c,i)=>'<span>'+c[1]+': <b>'+totalsByCol[i]+'/'+max+'</b></span>').join("");
 radarBox.innerHTML='<svg viewBox="0 0 360 320" aria-hidden="true">'+grid+spokes+'<polygon points="'+poly(shape)+'" fill="var(--accent)" fill-opacity=".22" stroke="var(--accent)" stroke-width="2"/>'+shape.map(p=>'<circle cx="'+p[0]+'" cy="'+p[1]+'" r="3" fill="var(--accent)"/>').join("")+labels+'</svg><div class="radar-legend">'+legend+'</div>';
}
function krender(){
 document.getElementById("orb").value=ORB;
 const groups={};K.forEach(u=>{(groups[u.name]=groups[u.name]||[]).push(u)});
 let names=Object.keys(groups).filter(n=>{const u=groups[n][0];return kf==="Tất cả"||u.phe===kf||(kf==="SSR+"&&u.r==="SSR+")||(kf==="SSR (nguyên liệu)"&&u.r==="SSR")});
 names.sort((a,b)=>(CORE.has(b)-CORE.has(a))||(groups[b][0].r==="SSR+")-(groups[a][0].r==="SSR+")||Math.max(...groups[b].map(u=>u.star))-Math.max(...groups[a].map(u=>u.star))||a.localeCompare(b,"vi"));
 document.getElementById("kList").innerHTML=names.map(n=>{const us=groups[n].sort((a,b)=>b.star-a.star),u0=us[0],h=byName[n];
  const tok=h?token(h):`<span class="token" style="background:${PHE_COLOR[u0.phe]||"var(--muted)"};font-size:11px">${esc(short(n))}</span>`;
  return `<div class="kh"><div class="kh-top">${tok}<div><b>${esc(n)}</b> ${CORE.has(n)?'<span class="tagcore">Đội chính</span>':""}<div class="meta">${esc(u0.phe)} · <span class="rarity">${u0.r}</span> · ${us.length} bản</div></div></div>
  <div class="units">${us.map(u=>`<span class="unit"><span class="unit-stars">${stars(u.star)}</span><button class="up" data-edit-star="${u.id}" title="Sửa số sao" aria-label="Sửa số sao bản ${u.star} sao">✎</button><button class="up" data-up="${u.id}" title="Nâng sao">▲ Nâng</button><button class="unit-del" data-del="${u.id}" title="Xóa bản này" aria-label="Xóa bản ${u.star} sao">✕</button></span>`).join("")}</div>
  <div class="kh-actions"><button class="btn ghost" data-copy-add="${esc(n)}" title="Thêm nhanh một bản trùng">＋ Bản trùng</button></div></div>`}).join("")||'<p class="empty">Không có tướng.</p>';
 document.getElementById("kLog").innerHTML=KLOG.slice().reverse().map(l=>`<li>${esc(l)}</li>`).join("")||'<li class="meta">Chưa có thao tác.</li>';
 document.getElementById("kUndo").disabled=!KUNDO.length;
 renderKhoMatrix();
}
document.getElementById("orb").addEventListener("change",e=>{snap();ORB=Math.max(0,+e.target.value||0);KLOG.push(`${today()} · Sửa cầu cam = ${ORB.toLocaleString("vi-VN")}`);ksave();krender();syncHeroes()});
document.getElementById("kUndo").onclick=()=>{const s=KUNDO.pop();if(!s)return;const o=JSON.parse(s);K=o.k;ORB=o.orb;KLOG=o.log;ksave();krender();syncHeroes()};
function modal(title,html,onok,okText="Xác nhận"){
 document.getElementById("dlg-token").innerHTML="";document.getElementById("dlg-title").textContent=title;document.getElementById("dlg-meta").textContent="";
 document.getElementById("dlg-body").innerHTML=html+`<div class="err" id="mErr"></div><div class="acts"><button class="btn ghost" id="mNo">Hủy</button><button class="btn" id="mOk">${okText}</button></div>`;
 document.getElementById("mNo").onclick=()=>dlg.close();document.getElementById("mOk").onclick=()=>{const r=onok();if(r)document.getElementById("mErr").textContent=r;else dlg.close()};dlg.showModal();}
document.getElementById("kList").addEventListener("click",e=>{
 const d=e.target.closest("[data-del]"),up=e.target.closest("[data-up]"),editStar=e.target.closest("[data-edit-star]"),copyAdd=e.target.closest("[data-copy-add]");
 if(copyAdd){const name=copyAdd.dataset.copyAdd,base=K.find(x=>x.name===name);if(!base)return;snap();const star=base.r==="SSR"?4:5;K.push({id:nid(),name:base.name,phe:base.phe,star,r:base.r});KLOG.push(`${today()} · Thêm nhanh 1 bản trùng ${base.name} ${stars(star)}`);ksave();krender();syncHeroes();return}
 if(editStar){const u=K.find(x=>x.id==editStar.dataset.editStar);if(!u)return;modal(`Sửa số sao · ${u.name}`,`<div class="form"><label for="editStarValue">Số sao hiện tại</label><input id="editStarValue" type="number" min="1" max="20" step="1" value="${u.star}"></div><p class="meta">Chỉ sửa số sao của bản tướng này; không thay đổi số bản trong kho.</p>`,()=>{const value=Number(document.getElementById("editStarValue").value);if(!Number.isInteger(value)||value<1||value>20)return "Nhập số sao nguyên từ 1 đến 20.";if(value===u.star)return "";snap();const before=u.star;u.star=value;KLOG.push(`${today()} · Sửa sao ${u.name}: ${stars(before)} → ${stars(value)}`);ksave();krender();syncHeroes();},"Lưu sao");return}
 if(d){const u=K.find(x=>x.id==d.dataset.del);modal(`Xóa ${u.name} ${stars(u.star)}?`,`<p>Dùng khi bản này đã bị tiêu hao ở việc khác hoặc nhập nhầm.</p>`,()=>{snap();K=K.filter(x=>x!==u);KLOG.push(`${today()} · Xóa ${u.name} ${stars(u.star)}`);ksave();krender();syncHeroes()},"Xóa");return}
 if(!up)return; const u=K.find(x=>x.id==up.dataset.up), R=RULE[u.star]||{copy:null,fs:null,fc:null,orb:null};
 const cand=K.filter(x=>x.id!==u.id&&(x.name===u.name||x.phe===u.phe)).sort((a,b)=>{const rk=x=>x.name===u.name?0:x.r==="SSR"?1:CORE.has(x.name)?3:2;return rk(a)-rk(b)||b.star-a.star||a.name.localeCompare(b.name,"vi")});
 const fmt=v=>v==null?"?":v;
 const hint=`<div class="hint">Gợi ý cho mốc <b>${stars(u.star)} → ${stars(u.star+1)}</b> (theo các ảnh đã gửi, kiểm tra lại trong game):<br>
  Bản trùng ${esc(u.name)}: <b>${R.copy==null?"?":R.copy?"1":"không cần"}</b> · Tướng ${esc(u.phe)} <b>${fmt(R.fs)}★ × ${fmt(R.fc)}</b> · Cầu cam <b>${R.orb==null?"?":R.orb.toLocaleString("vi-VN")}</b></div>`;
 const list=cand.map(x=>{const warn=CORE.has(x.name)&&x.name!==u.name;return `<label class="pick ${warn?"warn":""}"><input type="checkbox" value="${x.id}"> ${esc(x.name)} ${stars(x.star)} <span class="rarity">${x.r}</span>${x.name===u.name?" · bản trùng":""}${warn?" · ⚠ tướng đội chính":""}</label>`}).join("")||'<p class="meta">Không có tướng cùng phe.</p>';
 modal(`Nâng sao ${u.name}`,`${hint}<div class="form"><label for="mOrb">Cầu cam tiêu</label><input id="mOrb" type="number" min="0" value="${R.orb??0}"></div>
  <div><div class="rowlab">Chọn tướng làm nguyên liệu (sẽ bị trừ khỏi kho)</div><div class="picks">${list}</div></div>`,()=>{
   const cost=Math.max(0,+document.getElementById("mOrb").value||0); if(cost>ORB) return `Không đủ cầu cam: có ${ORB.toLocaleString("vi-VN")}, cần ${cost.toLocaleString("vi-VN")}.`;
   const ids=[...document.querySelectorAll("#dlg-body .picks input:checked")].map(i=>+i.value);
   const validation=validateUpgrade(u,ids);if(validation)return validation;
   snap(); const used=K.filter(x=>ids.includes(x.id)); K=K.filter(x=>!ids.includes(x.id)); u.star++; ORB-=cost;
   KLOG.push(`${today()} · ${u.name} ${stars(u.star-1)}→${stars(u.star)} · −${cost.toLocaleString("vi-VN")} cầu${used.length?" · tiêu: "+used.map(x=>x.name+" "+stars(x.star)).join(", "):""}`);
   ksave();krender();syncHeroes();},"Nâng sao");});
