/* ===== ĐỐI ĐẦU ===== */
const EDB=Object.fromEntries(([["Lữ Bố", "3Q", ["carry", "rageDep"], "Carry đánh thường, mạnh theo Nộ"], ["Lý Long Cơ", "Đường", ["sub", "amp"], "Gắn [Trường Hận] tăng ST mục tiêu phải chịu"], ["Điêu Thuyền", "3Q", ["heal", "cleanse"], "Hồi máu lớn; 11★ gánh khống chế cho carry"], ["Vương Chiêu Quân", "Hán", ["buff", "shield"], "Buff Công, khiên toàn đội (11★)"], ["Ban Chiêu", "Hán", ["heal", "buff"], "Hồi máu đều, buff Bạo Kích (11★)"], ["Lỗ Trí Thâm", "Đường", ["tank", "ctrl", "aoe"], "Tank khiêu khích"], ["Quỷ Cốc Tử", "Tần", ["back", "rage-", "aoe"], "Đánh hàng sau, cướp Nộ"], ["Triệu Vân", "3Q", ["aoe", "sub"], "Đòn mở màn toàn địch, tự choáng 2 hiệp"], ["Hàn Tín", "Hán", ["tank"], "Tank [Bá Vương]"], ["Chân Cơ", "3Q", ["shield"], "Khiên toàn đội"], ["Tây Thi", "Tần", ["heal", "buff"], "Healer chính, hồi 2 người ít HP"], ["Thái Văn Cơ", "3Q", ["heal", "rage+"], "Hồi toàn đội, 11★ cấp Nộ"], ["Lưu Bang", "Hán", ["carry"], "Carry 3 đòn ngẫu nhiên"], ["Ngu Cơ", "Hán", ["carry", "aoe"], "Carry đánh toàn địch"], ["Tư Mã Ý", "3Q", ["carry"], "Carry mạnh dần theo trận"], ["Chung Vô Diệm", "Tần", ["carry"], "Carry đơn mục tiêu, lật kèo"], ["Biển Thước", "Tần", ["heal", "shield", "revive"], "Healer, Khiên Vô Địch, hồi sinh"], ["Can Tương", "Tần", ["dot", "aoe"], "Rải [Huyết Tích]"], ["Thượng Quan Uyển Nhi", "Đường", ["shield"], "Chia sẻ sát thương"], ["Lý Bạch", "Đường", ["carry", "aoe", "immune"], "Carry toàn địch, miễn khống sau tuyệt chiêu"], ["Tôn Sách", "3Q", ["back", "sub"], "Đánh hàng sau, truy kích, phá Thủ"], ["Quan Vũ", "3Q", ["carry", "exec"], "Đánh địch %HP thấp nhất"], ["Lý Thế Dân", "Đường", ["tank", "shield"], "Tank khiên toàn đội"], ["Vệ Thanh", "Hán", ["back", "sub", "rage+"], "Đánh hàng sau, bảo vệ đồng đội yếu máu"], ["Gia Cát Lượng", "3Q", ["ctrl", "aoe"], "Choáng diện rộng"], ["Võ Tắc Thiên", "Đường", ["aoe", "dispel", "rage+"], "Xóa buff/khiên địch, cấp Nộ"], ["Bạch Khởi", "Tần", ["tank", "dot"], "Tank phản [Huyết Tích]"], ["Tần Thủy Hoàng", "Tần", ["carry", "aoe", "dot"], "Carry toàn địch [Huyết Tích]"], ["Dương Ngọc Hoàn", "Đường", ["rage-", "ctrl"], "Giảm Nộ địch – khắc chế Lữ Bố"], ["Hồng Phất Nữ", "Đường", ["heal"], "Trị liệu (theo huy hiệu)"], ["Thương Ưởng", "Tần", ["ctrl"], "Câm lặng khống chế (theo huy hiệu)"]]).map(([n,p,t,d])=>[n,{name:n,phe:p,tags:t,desc:d}]));
const TAGN={carry:"Carry",sub:"ST phụ",heal:"Hồi máu",tank:"Tank",shield:"Khiên",ctrl:"Khống chế",buff:"Buff","rage+":"Cấp Nộ","rage-":"Giảm/cướp Nộ",dispel:"Xóa buff",back:"Đánh hàng sau",aoe:"Diện rộng",exec:"Kết liễu",dot:"Chảy máu",cleanse:"Giải khống",amp:"Khuếch đại ST",immune:"Miễn khống",revive:"Hồi sinh",rageDep:"Phụ thuộc Nộ"};
const EDIT=["carry","heal","tank","shield","ctrl","rage-","back","aoe","dispel","buff"];
let VS; try{VS=JSON.parse(localStorage.getItem("vs2")||"null")}catch(e){} VS=VS||{slots:Array.from({length:6},()=>({n:"",tags:[]})),lv:"",my:""};
const vsSave=()=>{try{localStorage.setItem("vs2",JSON.stringify(VS))}catch(e){}};
const allNames=()=>[...new Set([...Object.keys(EDB),...H.map(h=>h.name)])].sort((a,b)=>a.localeCompare(b,"vi"));
function vsSlots(){
 document.getElementById("vsSlots").innerHTML=`<datalist id="edl">${allNames().map(n=>`<option value="${esc(n)}">`).join("")}</datalist>`+VS.slots.map((s,i)=>{
  const known=EDB[s.n]; const tags=known?known.tags:s.tags;
  return `<div class="vslot ${i<3?"front":"back"}"><div class="rowlab">Ô ${i+1} · ${i<3?"Hàng trước":"Hàng sau"}</div>
   <input list="edl" data-slot="${i}" value="${esc(s.n)}" placeholder="Tên tướng địch" aria-label="Ô ${i+1}">
   <div class="tagrow">${known?tags.map(t=>`<span class="tg fixed" aria-pressed="true">${TAGN[t]||t}</span>`).join("")+`<span class="meta" style="font-size:11px">${esc(known.desc)}</span>`
     :s.n?EDIT.map(t=>`<button class="tg" data-slot="${i}" data-tag="${t}" aria-pressed="${tags.includes(t)}">${TAGN[t]}</button>`).join("")+'<span class="meta" style="font-size:11px">Tướng chưa có dữ liệu – chọn vai trò</span>':""}</div></div>`}).join("");
 document.getElementById("vsLv").value=VS.lv; document.getElementById("vsMy").value=VS.my;
}
document.getElementById("vsSlots").addEventListener("change",e=>{const i=e.target.dataset.slot;if(i==null||e.target.tagName!=="INPUT")return;VS.slots[i]={n:e.target.value.trim(),tags:[]};vsSave();vsSlots()});
document.getElementById("vsSlots").addEventListener("click",e=>{const b=e.target.closest("button[data-tag]");if(!b)return;const s=VS.slots[b.dataset.slot],t=b.dataset.tag;s.tags=s.tags.includes(t)?s.tags.filter(x=>x!==t):[...s.tags,t];vsSave();vsSlots()});
document.getElementById("vsClr").onclick=()=>{VS={slots:Array.from({length:6},()=>({n:"",tags:[]})),lv:"",my:""};vsSave();vsSlots();document.getElementById("vsOut").innerHTML=""};
["vsLv","vsMy"].forEach(id=>document.getElementById(id).addEventListener("change",e=>{VS[id==="vsLv"?"lv":"my"]=e.target.value;vsSave()}));
const partner=n=>{const h=byName[n];return h?(h.tn||"").split(" – ")[0].split(" (")[0].trim():""};
function vsRun(){
 const en=VS.slots.map((s,i)=>({...s,i,tags:EDB[s.n]?EDB[s.n].tags:s.tags})).filter(s=>s.n);
 if(!en.length){document.getElementById("vsOut").innerHTML='<p class="empty">Nhập ít nhất 1 tướng địch.</p>';return}
 const has=t=>en.filter(s=>s.tags.includes(t)); const pos=s=>`Ô${s.i+1}`;
 const carries=has("carry"),heals=has("heal"),tanks=[...has("tank"),...has("shield")],ctrl=has("ctrl"),drain=has("rage-"),backHeal=heals.filter(s=>s.i>=3),shields=has("shield"),buffs=has("buff");
 const T=[];
 if(carries.length) T.push(["hi","Carry địch",carries.map(s=>`${s.n} (${pos(s)})`).join(", ")+" – mục tiêu cần hạ hoặc chặn sớm."]); else T.push(["md","Carry địch","Chưa nhận diện được carry. Kiểm tra lại tướng chưa có dữ liệu."]);
 if(heals.length) T.push([heals.length>1?"hi":"md","Hồi máu",heals.map(s=>`${s.n} (${pos(s)})`).join(", ")+(backHeal.length?" – đứng hàng sau, cần tướng đánh hàng sau.":"")]);
 if(tanks.length) T.push(["md","Tank / khiên",tanks.map(s=>`${s.n} (${pos(s)})`).join(", ")+(shields.length?" – khiên làm chậm sát thương, Võ Tắc Thiên xóa được.":"")]);
 if(drain.length) T.push(["hi","Giảm Nộ",drain.map(s=>s.n).join(", ")+" – khắc chế Lữ Bố (sức mạnh theo Nộ)."]);
 if(ctrl.length) T.push(["md","Khống chế",ctrl.map(s=>s.n).join(", ")+" – cần giải khống (Điêu Thuyền 11★) hoặc miễn khống (Lý Bạch)."]);
 const lv=+VS.lv, my=+VS.my; if(lv&&my&&lv-my>=10) T.push(["hi","Chênh cấp",`Địch cao hơn ${lv-my} cấp. Đổi đội hình khó bù được; nên nâng cấp trước.`]);
 // chấm điểm tướng sở hữu
 const own={}; K.filter(u=>u.r==="SSR+").forEach(u=>{own[u.name]=Math.max(own[u.name]||0,u.star)});
 const tagOf=n=>(EDB[n]||{tags:[]}).tags;
 const sc={},why={};
 Object.entries(own).forEach(([n,st])=>{const tg=tagOf(n),h=byName[n];let s=(h&&h.pvp!=null?h.pvp:2.5)+Math.min(st-5,6)*0.8;const w=[];let cb=0;const add=(v,m)=>{cb+=v;w.push(m)};
  if(backHeal.length&&(tg.includes("back")||tg.includes("aoe")))add(1.5,"đánh tới healer hàng sau")
  if(carries.length&&tg.includes("exec"))add(0.8,"kết liễu từng mục tiêu")
  if((shields.length||buffs.length)&&tg.includes("dispel"))add(2,"xóa khiên/buff địch")
  if(carries.length&&(tg.includes("shield")||tg.includes("tank")))add(1,"chịu đòn từ carry địch")
  if(drain.length&&tg.includes("rageDep")){s-=0.5;w.push("bị giảm Nộ khắc chế")}
  if(drain.length&&(tg.includes("rage+")||tg.includes("immune")))add(0.8,"bù Nộ / không phụ thuộc Nộ")
  if(ctrl.length&&(tg.includes("cleanse")||tg.includes("immune")))add(1,"chống khống chế")
  if(en.some(e=>e.tags.includes("rageDep")||e.tags.includes("carry"))&&tg.includes("rage-"))add(0.8,"cướp Nộ carry địch")
  sc[n]=s+Math.min(cb,2);why[n]=w;});
 const pick=[],take=n=>{if(n&&!pick.includes(n))pick.push(n)};
 const best=f=>Object.keys(sc).filter(n=>!pick.includes(n)&&f(tagOf(n))).sort((a,b)=>sc[b]-sc[a])[0];
 const carry=best(t=>t.includes("carry")); take(carry);
 take(best(t=>t.includes("heal")));
 take(best(t=>t.includes("tank")||t.includes("shield")));
 if(carry==="Lữ Bố"&&own["Lý Long Cơ"]) take("Lý Long Cơ");
 while(pick.length<6){const cand=Object.keys(sc).filter(n=>!pick.includes(n)).map(n=>{let v=sc[n];const t=tagOf(n);
   if(pick.some(p=>partner(p)===n||partner(n)===p))v+=1.2; if(t.includes("carry"))v-=1.5; if(t.includes("heal")&&pick.filter(p=>tagOf(p).includes("heal")).length>=2)v-=2; return [n,v]}).sort((a,b)=>b[1]-a[1]);
   if(!cand.length)break; take(cand[0][0]);}
 const reach=n=>tagOf(n).includes("back")||(tagOf(n).includes("aoe")&&n!==carry);
 if(backHeal.length&&!pick.some(reach)){const hb=Object.keys(sc).filter(n=>!pick.includes(n)&&reach(n)).sort((a,b)=>sc[b]-sc[a])[0];
  if(hb){const locked=new Set([carry,pick[1],pick[2],"Lý Long Cơ"]);const out=pick.filter(n=>!locked.has(n)).sort((a,b)=>sc[a]-sc[b])[0];
   if(out){pick.splice(pick.indexOf(out),1,hb);why[hb]=[...(why[hb]||[]),`thay ${out} để có người đánh tới healer hàng sau`];}}}
 // xếp ô
 const isFront=n=>{const t=tagOf(n);return t.includes("tank")||t.includes("shield")||n==="Lý Long Cơ"||t.includes("ctrl")};
 let front=pick.filter(isFront).sort((a,b)=>(a==="Lý Long Cơ")-(b==="Lý Long Cơ")).reverse(), back=pick.filter(n=>!isFront(n));
 while(front.length>3) back.push(front.pop());
 const order=n=>tagOf(n).includes("carry")?0:tagOf(n).includes("heal")?2:1;
 back.sort((a,b)=>order(a)-order(b)); while(front.length<3&&back.length>3){const m=back.find(n=>!tagOf(n).includes("carry")&&!tagOf(n).includes("heal"))||back[back.length-1];back=back.filter(x=>x!==m);front.push(m)}
 // Lý Long Cơ ô1, carry ô4 cùng làn
 if(front.includes("Lý Long Cơ")) front=["Lý Long Cơ",...front.filter(n=>n!=="Lý Long Cơ")];
 const slots=[...front,...Array(Math.max(0,3-front.length)).fill(""),...back].slice(0,6);
 const bonds=pick.filter(n=>pick.includes(partner(n))).map(n=>`${n} + ${partner(n)}`).filter((v,i,a)=>a.findIndex(x=>x.split(" + ").sort().join()===v.split(" + ").sort().join())===i);
 const warns=[]; const hiAtk=pick.filter(n=>n==="Vệ Thanh"||n==="Quan Vũ"||n==="Lý Thế Dân"); if(carry&&hiAtk.length&&!hiAtk.includes(carry)) warns.push(`${hiAtk.join(", ")} có Công cao, có thể chiếm vị trí "Công cao nhất" của ${carry} khi đồng đội có hiệu ứng 9★ nhắm Công cao nhất.`);
 if(drain.length&&carry==="Lữ Bố") warns.push("Địch có giảm Nộ: cân nhắc Lý Bạch hoặc Quan Vũ làm carry thay Lữ Bố nếu thua nhiều.");
 const cell=n=>{if(!n)return'<div class="slot" style="opacity:.5"><span class="nm">Trống</span></div>';const h=byName[n]||{name:n,phe:(EDB[n]||{}).phe||"3Q"};return `<button class="slot" data-h="${esc(n)}">${token(h)}<span class="nm">${esc(n)}</span><span class="tg">${own[n]}★</span></button>`};
 document.getElementById("vsOut").innerHTML=`<div class="vsres">
  <div class="panel"><h3>Phân tích đội địch</h3><div class="threat">${T.map(([l,a,b])=>`<div class="th"><span class="lv ${l}">${a}</span><span>${esc(b)}</span></div>`).join("")}</div></div>
  <div class="board"><div class="board-head"><h3>Đội gợi ý từ kho</h3></div>
   <div class="enemy">↑ Phía địch</div><div class="rowlab">Hàng trước</div><div class="row front">${slots.slice(0,3).map(cell).join("")}</div>
   <div class="rowlab">Hàng sau</div><div class="row back">${slots.slice(3).map(cell).join("")}</div>
   <div class="bonds">${bonds.map(b=>`<span class="chip on">Tình Nghĩa: ${esc(b)}</span>`).join("")}</div></div></div>
  <div class="panel" style="margin-top:16px"><h3>Lý do chọn</h3><ul>${pick.map(n=>`<li><b>${esc(n)}</b> (${own[n]}★): ${esc((EDB[n]||{}).desc||"")}${why[n]&&why[n].length?" – "+esc(why[n].join(", ")):""}</li>`).join("")}</ul>
  ${warns.length?`<h3 style="margin-top:12px">Lưu ý</h3><ul>${warns.map(w=>`<li>${esc(w)}</li>`).join("")}</ul>`:""}</div>`;
}
document.getElementById("vsGo").onclick=vsRun;
document.getElementById("vsOut").addEventListener("click",e=>{const b=e.target.closest("[data-h]");if(b&&byName[b.dataset.h])openHero(b.dataset.h)});
vsSlots();

