/* ===== CÔNG CỤ PHÂN TÍCH TƯỚNG ===== */
const analysisPhe=document.getElementById("analysis-phe");
const analysisNhom=document.getElementById("analysis-nhom");
const analysisQ=document.getElementById("analysis-q");
const analysisResults=document.getElementById("analysis-results");
const analysisCount=document.getElementById("analysis-count");
const analysisHero1=document.getElementById("analysis-hero1");
const analysisHero2=document.getElementById("analysis-hero2");
const analysisCompare=document.getElementById("analysis-compare");
const analysisScore=v=>v==null?"—":Number(v).toFixed(1);
function analysisCard(h){
  const totalScore=["pvp","boss","pve"].filter(k=>h[k]!=null).length
    ?(["pvp","boss","pve"].reduce((n,k)=>n+(Number(h[k])||0),0)/["pvp","boss","pve"].filter(k=>h[k]!=null).length).toFixed(1):"—";
  return '<article class="card analysis-card"><div class="card-top">'+token(h)+'<div><h4>'+esc(h.name)+'</h4><div class="meta">'+esc(h.phe||"Chưa rõ phe")+' · '+esc(h.nhom||"Chưa rõ nhóm")+' · '+esc(h.sao??"—")+'★</div></div></div>'+
    '<div class="analysis-scores"><span>PVP '+analysisScore(h.pvp)+'</span><span>Boss '+analysisScore(h.boss)+'</span><span>PVE '+analysisScore(h.pve)+'</span><span>TB '+totalScore+'</span></div>'+
    '<div class="meta">'+esc(h.role||"Chưa có mô tả vai trò")+'</div><div class="r">'+esc(h.base||"Chưa có mô tả kỹ năng cơ bản")+'</div></article>';
}
function renderAnalysisList(){
  if(!analysisResults)return;
  const q=(analysisQ?.value||"").trim().toLocaleLowerCase("vi");
  const list=H.filter(h=>(!analysisPhe.value||h.phe===analysisPhe.value)&&(!analysisNhom.value||h.nhom===analysisNhom.value)&&
    (!q||[h.name,h.role,h.base,h.s9,h.s11,h.s13,h.nt,h.phe,h.nhom].join(" ").toLocaleLowerCase("vi").includes(q)));
  list.sort((a,b)=>a.name.localeCompare(b.name,"vi"));
  analysisCount.textContent="Tìm thấy "+list.length+" / "+H.length+" tướng.";
  analysisResults.innerHTML=list.map(analysisCard).join("")||'<p class="empty">Không có tướng phù hợp bộ lọc.</p>';
}
function analysisCompareCard(h){
  const row=(label,value)=>'<dt>'+label+'</dt><dd>'+esc(value??"Chưa có dữ liệu")+'</dd>';
  return '<article class="analysis-compare-card"><h4>'+esc(h.name)+'</h4><dl>'+
    row("Phe",h.phe)+row("Nhóm",h.nhom)+row("Sao hiện tại",(h.sao??"—")+"★")+
    row("Vai trò",h.role)+row("PVP",analysisScore(h.pvp))+
    row("Boss",analysisScore(h.boss))+row("PVE",analysisScore(h.pve))+
    row("Duyên phận",h.tn)+'</dl>'+
    '<div class="analysis-skill"><b>Cơ bản:</b> '+esc(h.base||"Chưa có dữ liệu")+'</div>'+
    '<div class="analysis-skill"><b>Mốc 9★:</b> '+esc(h.s9||"Chưa có dữ liệu")+'</div>'+
    '<div class="analysis-skill"><b>Mốc 11★:</b> '+esc(h.s11||"Chưa có dữ liệu")+'</div>'+
    '<div class="analysis-skill"><b>Mốc 13★:</b> '+esc(h.s13||"Chưa có dữ liệu")+'</div>'+
    (h.nt?'<div class="analysis-skill"><b>Cơ chế Nộ:</b> '+esc(h.nt)+'</div>':"")+'</article>';
}
function renderAnalysisCompare(){
  if(!analysisCompare||!H.length)return;
  const a=byName[analysisHero1.value]||H[0];
  const b=byName[analysisHero2.value]||H[Math.min(1,H.length-1)];
  analysisCompare.innerHTML='<div class="analysis-compare-grid">'+analysisCompareCard(a)+analysisCompareCard(b)+'</div>';
}
const analysisNames=H.map(h=>h.name).sort((a,b)=>a.localeCompare(b,"vi"));
[analysisHero1,analysisHero2].forEach((sel,i)=>{
  if(!sel)return;
  sel.innerHTML=analysisNames.map(n=>'<option value="'+esc(n)+'">'+esc(n)+'</option>').join("");
  sel.value=analysisNames.includes(i===0?"Lữ Bố":"Điêu Thuyền")?(i===0?"Lữ Bố":"Điêu Thuyền"):analysisNames[i]||"";
});
analysisPhe?.addEventListener("change",renderAnalysisList);
analysisNhom?.addEventListener("change",renderAnalysisList);
analysisQ?.addEventListener("input",renderAnalysisList);
analysisHero1?.addEventListener("change",renderAnalysisCompare);
analysisHero2?.addEventListener("change",renderAnalysisCompare);
renderAnalysisList();
renderAnalysisCompare();

